import{_ as t,o as e,c as l,ag as o}from"./chunks/framework.OsDJF_Ea.js";const u=JSON.parse('{"title":"메시지","description":"","frontmatter":{},"headers":[],"relativePath":"02-user-guide/messaging.md","filePath":"02-user-guide/messaging.md","lastUpdated":1776160579000}'),i={name:"02-user-guide/messaging.md"};function r(d,a,s,n,h,c){return e(),l("div",null,[...a[0]||(a[0]=[o(`<h1 id="메시지" tabindex="-1">메시지 <a class="header-anchor" href="#메시지" aria-label="Permalink to &quot;메시지&quot;">​</a></h1><p>채널과 토픽에서 팀원과 메시지를 주고받을 수 있습니다.</p><h2 id="메시지-보내기" tabindex="-1">메시지 보내기 <a class="header-anchor" href="#메시지-보내기" aria-label="Permalink to &quot;메시지 보내기&quot;">​</a></h2><ol><li>채널 또는 토픽의 상세 화면으로 이동합니다.</li><li>하단의 입력창에 메시지를 작성합니다.</li><li>Enter 키 또는 전송 버튼을 클릭합니다.</li></ol><h2 id="쓰레드-답글" tabindex="-1">쓰레드 (답글) <a class="header-anchor" href="#쓰레드-답글" aria-label="Permalink to &quot;쓰레드 (답글)&quot;">​</a></h2><p>특정 메시지에 대한 답글을 쓰레드로 관리합니다.</p><ol><li>메시지에 마우스를 올리면 액션 버튼이 표시됩니다.</li><li><strong>답글</strong> 아이콘을 클릭합니다.</li><li>우측에 쓰레드 패널이 열리고, 해당 메시지에 대한 답글을 작성합니다.</li></ol><h2 id="멘션" tabindex="-1">멘션 (@) <a class="header-anchor" href="#멘션" aria-label="Permalink to &quot;멘션 (@)&quot;">​</a></h2><p>메시지 입력창에서 <code>@</code>를 입력하면 멘션 대상 목록이 표시됩니다.</p><h3 id="멘션-대상-유형" tabindex="-1">멘션 대상 유형 <a class="header-anchor" href="#멘션-대상-유형" aria-label="Permalink to &quot;멘션 대상 유형&quot;">​</a></h3><table tabindex="0"><thead><tr><th>구분</th><th>설명</th><th>예시</th></tr></thead><tbody><tr><td><strong>사람</strong></td><td>특정 사용자에게 알림 전송</td><td><code>@홍길동</code></td></tr><tr><td><strong>조직</strong></td><td>부서 전체에 알림 전송</td><td><code>@개발팀</code></td></tr><tr><td><strong>봇</strong></td><td>봇에게 질문/명령 전달</td><td><code>@검색봇 최근 공지사항</code></td></tr><tr><td><strong>특수</strong></td><td>채널 전체 알림</td><td><code>@all</code>, <code>@here</code></td></tr></tbody></table><h3 id="봇-멘션" tabindex="-1">@봇 멘션 <a class="header-anchor" href="#봇-멘션" aria-label="Permalink to &quot;@봇 멘션&quot;">​</a></h3><p>채널, 토픽, DM에서 <code>@봇이름</code>으로 봇에게 직접 메시지를 전달할 수 있습니다.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>@검색봇 지난주 회의록 찾아줘</span></span>
<span class="line"><span>@태스크봇 마감 임박 태스크 알려줘</span></span></code></pre></div><ul><li>봇이 메시지를 분석하여 <strong>쓰레드(답글)</strong> 형태로 응답합니다</li><li>채널, 프로젝트 토픽, DM 어디에서나 사용 가능합니다</li><li>멘션 목록에서 봇은 <strong>봇</strong> 배지로 구분됩니다</li></ul><h2 id="리액션" tabindex="-1">리액션 <a class="header-anchor" href="#리액션" aria-label="Permalink to &quot;리액션&quot;">​</a></h2><p>메시지에 이모지로 반응할 수 있습니다.</p><ol><li>메시지에 마우스를 올려 이모지 아이콘을 클릭합니다.</li><li>원하는 이모지를 선택합니다.</li><li>같은 이모지를 다시 클릭하면 취소됩니다.</li></ol><h2 id="메시지-고정" tabindex="-1">메시지 고정 <a class="header-anchor" href="#메시지-고정" aria-label="Permalink to &quot;메시지 고정&quot;">​</a></h2><p>중요한 메시지를 고정하여 쉽게 찾을 수 있습니다.</p><ol><li>메시지의 <strong>핀</strong> 아이콘을 클릭합니다.</li><li>고정된 메시지는 상단에 표시됩니다.</li></ol><h2 id="메시지-수정-및-삭제" tabindex="-1">메시지 수정 및 삭제 <a class="header-anchor" href="#메시지-수정-및-삭제" aria-label="Permalink to &quot;메시지 수정 및 삭제&quot;">​</a></h2><ul><li><strong>수정</strong>: 메시지 액션 메뉴 &gt; 수정을 클릭하여 내용을 변경합니다.</li><li><strong>삭제</strong>: 메시지 액션 메뉴 &gt; 삭제를 클릭합니다. 본인이 작성한 메시지만 삭제 가능합니다.</li></ul><h2 id="메시지에서-태스크-생성" tabindex="-1">메시지에서 태스크 생성 <a class="header-anchor" href="#메시지에서-태스크-생성" aria-label="Permalink to &quot;메시지에서 태스크 생성&quot;">​</a></h2><p>메시지 내용을 기반으로 태스크를 바로 생성할 수 있습니다.</p><ol><li>메시지 액션 메뉴에서 **&quot;태스크 만들기&quot;**를 클릭합니다.</li><li>태스크 제목과 상세 정보를 입력합니다.</li><li>생성된 태스크는 해당 토픽의 태스크 보드에 추가됩니다.</li></ol>`,26)])])}const g=t(i,[["render",r]]);export{u as __pageData,g as default};
